@startuml

class Person {
  + personID : int
  + phoneNumber : string
  + keywords : string[]
}

class ResearchInstitution {
  + institutionCode : int
}

class ScientificArticle {
  + DOI : string
  + title : string
}

class PeerReviewedPaper {
  + citationCount : int
}

class TechnicalReport {}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + impactFactor : float
}

class AuthorPosition {
  + position : int
}

class Reviewer {}

Person "1" -- "1" ResearchInstitution : worksFor
Person "1" -- "0..*" ScientificArticle : author
Person "1" -- "0..*" ScientificArticle : reviewer

ScientificArticle "1" -- "1..*" AuthorPosition
AuthorPosition "*" -- "1" Person

PeerReviewedPaper --|> ScientificArticle
TechnicalReport --|> ScientificArticle

TechnicalReport "*" -- "1" ResearchInstitution : publishedBy

PeerReviewedPaper "*" -- "1" Journal : publishedIn
Publisher "1" -- "1..*" Journal : publishes
ResearchInstitution "0..*" -- "0..*" Journal : subscribes

@enduml

